import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, expectResult, field, SET1, DEVICES } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — формулы и крайние случаи', () => {
  for (const tag of DEVICES) {
    test(`«₪ 750,000» и «1,000» принимаются; поле форматируется на blur #d45b2a ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);
      const price = field(page, 'purchasePrice');
      const setup = field(page, 'setupCosts');

      await fillInputs(page, { ...SET1, purchasePrice: '₪ 750,000', setupCosts: '1,000' });
      await field(page, 'inventory').focus();
      await expect(price).toHaveValue('750,000');
      await expect(setup).toHaveValue('1,000');
      await expect(price).toHaveAttribute('aria-invalid', 'false');
      await expect(setup).toHaveAttribute('aria-invalid', 'false');
      await expect(page.locator('#calc-purchasePrice-error')).toHaveCount(0);
      await expect(page.locator('#calc-setupCosts-error')).toHaveCount(0);
      await expectResult(page, 'סך השקעה ראשונית', '801,000 ₪');
      await expectResult(page, 'הון עצמי נדרש', '601,000 ₪');

      await price.fill('500000');
      await expect(price).toHaveValue('500000');
      await field(page, 'inventory').focus();
      await expect(price).toHaveValue('500,000');
      await expectResult(page, 'סך השקעה ראשונית', '551,000 ₪');
    });
  }
});
